def fig(name, cap):
    v = V[name]; return f'<figure markdown>\n--8<-- "{v["file"]}"\n<figcaption>{cap}</figcaption>\n</figure>\n\n'
for n in range(1, 16):
    p = os.path.join(DOCS, "workbook", f"lab-{n:02d}.md"); s = open(p, encoding="utf-8").read(); crlf = "\r\n" in s; s = s.replace("\r\n", "\n")
    if "<!-- rsv-lab -->" in s: continue
    wf = fig(f"lab{n:02d}-workflow", f"លំដាប់ការងារនៃលំហាត់ទី{kh(n)} និងពេលវេលាប្រហាក់ប្រហែល។")
    m = re.search(r"^## គោលបំណង\n(?:.*\n)*?(?=^## )", s, re.M)
    if m: s = s[:m.end()] + "<!-- rsv-lab -->\n" + wf + s[m.end():]
    else: s = re.sub(r"(^# .+\n)", r"\1\n<!-- rsv-lab -->\n" + wf.replace("\\", "\\\\"), s, 1, flags=re.M)
    exp = "## លទ្ធផលដែលរំពឹងទុក\n\nប្រៀបធៀបលទ្ធផលរបស់អ្នកជាមួយរូបខាងក្រោម ដែលបង្កើតពីទិន្នន័យវគ្គ (Landsat 8 ភ្នំពេញ ឬ Sentinel-2 ក្រុងព្រះសីហនុ)។ លទ្ធផលរបស់អ្នកមិនចាំបាច់ដូចបេះបិទទេ ប៉ុន្តែលំនាំគួរតែស្រដៀងគ្នា។\n\n"
    for i, name in enumerate(EXPECT[n], 1):
        v = V[name]; exp += fig(name, f"លទ្ធផលគំរូ {kh(i)}៖ {v['title']}។") + "!!! tip \"អ្វីដែលត្រូវពិនិត្យ\"\n" + "".join(f"    - {b}\n" for b in v["bullets"]) + "\n"
    exp += "## កំហុសទូទៅ និងដំណោះស្រាយ\n\n| បញ្ហាដែលឃើញ | មូលហេតុទូទៅ | ដំណោះស្រាយ |\n|---|---|---|\n" + "".join(f"| {a} | {b} | {c} |\n" for a, b, c in ERR[n]) + "\n"
    k = s.find("## លទ្ធផលត្រូវប្រគល់")
    s = (s[:k] + exp + s[k:]) if k >= 0 else s.rstrip() + "\n\n" + exp
    open(p, "w", encoding="utf-8").write(s.replace("\n", "\r\n") if crlf else s)
    print(f"lab {n:02d}: +{1 + len(EXPECT[n])} figures, +errors table ({len(s)} chars)")
